package com.physio.assistant.entity;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "session_events", uniqueConstraints = @UniqueConstraint(columnNames = {"session_id", "event_uid"}))
@Getter
@Setter
public class SessionEvent {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "session_id")
    private Session session;

    // Idempotency key generated by whoever produces the event (AI service / edge device),
    // so a retried write after a network blip never creates a duplicate row.
    @Column(name = "event_uid", nullable = false, length = 64)
    private String eventUid;

    @Column(name = "sequence_no", nullable = false)
    private Integer sequenceNo;

    @Column(name = "event_timestamp", nullable = false)
    private LocalDateTime eventTimestamp;

    @Column(name = "joint_name", length = 50)
    private String jointName;

    @Column(name = "deviation_value", precision = 6, scale = 2)
    private BigDecimal deviationValue;

    @Column(name = "feedback_message", length = 255)
    private String feedbackMessage;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 30)
    private Source source = Source.GEOMETRIC_COMPARISON;

    @Column(name = "event_type", length = 30)
    private String eventType;

    @Column(name = "error_code", length = 50)
    private String errorCode;

    @Column(name = "rep_number")
    private Integer repNumber;

    public enum Source { GEOMETRIC_COMPARISON, CLASSIFIER, ON_DEVICE_RULES }
}
